library "org.ltl"
/// One weight break.
type Break = { from: Weight, rate: Money/cwt, minimum: Money? }
enum Tier { Low, High }
const FLOOR: Money = $50
fn billed(weight: Weight, to: Weight = 100 lb) -> Weight = weight.roundUp(to: to)
fn cheapest(breaks: List<Break>, actual: Weight) -> Money = breaks.map(b => b.rate * actual).min() ?? FLOOR

